import{_ as o,o as t,c as n,a6 as r}from"./chunks/framework.BBdhcoHf.js";const u=JSON.parse('{"title":"ADR-012: WebSocket Transport Design Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"adr/012-websocket-transport-design.md","filePath":"adr/012-websocket-transport-design.md","lastUpdated":1771970963000}'),i={name:"adr/012-websocket-transport-design.md"};function s(a,e,l,c,d,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /adr/012-websocket-transport-design.md for this page in Markdown format</div><h1 id="adr-012-websocket-transport-design-decisions" tabindex="-1">ADR-012: WebSocket Transport Design Decisions <a class="header-anchor" href="#adr-012-websocket-transport-design-decisions" aria-label="Permalink to “ADR-012: WebSocket Transport Design Decisions”">​</a></h1><ul><li><strong>Date</strong>: 2025-01-13</li><li><strong>Status</strong>: Accepted</li><li><strong>Applies to</strong>: @sideband/transport-ws</li><li><strong>Tags</strong>: transport, websocket, api-design</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The <code>@sideband/transport-ws</code> package implements the Transport ABI (ADR-005) for WebSocket connections. Several API design decisions required choosing between alternatives with different tradeoffs for usability, security, and correctness.</p><p>This ADR documents the key decisions and rejected alternatives for future reference.</p><h2 id="architectural-invariants" tabindex="-1">Architectural Invariants <a class="header-anchor" href="#architectural-invariants" aria-label="Permalink to “Architectural Invariants”">​</a></h2><p>These constraints are non-negotiable and apply to all decisions below:</p><ol><li><p><strong>Opaque payloads</strong>: Transport MUST treat message payloads as opaque bytes. No SBP/SBRP/RPC semantics at this layer. This preserves layer boundaries and future-proofs alternative session stacks.</p></li><li><p><strong>Topology-agnostic</strong>: Transport behavior MUST NOT branch on relay vs direct topology. Only endpoint URLs and options differ. Runtime stays topology-agnostic.</p></li><li><p><strong>No reconnection</strong>: Transport only reports state, close, and errors. Reconnection and backoff policies belong in <code>@sideband/runtime</code> or <code>@sideband/peer</code>. This avoids hidden policies and keeps transport minimal.</p></li></ol><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to “Decisions”">​</a></h2><h3 id="_1-single-entry-point-vs-separate-browser-node-exports" tabindex="-1">1. Single entry point vs separate browser/node exports <a class="header-anchor" href="#_1-single-entry-point-vs-separate-browser-node-exports" aria-label="Permalink to “1. Single entry point vs separate browser/node exports”">​</a></h3><p><strong>Options</strong>:</p><ul><li>A) Single <code>wsTransport()</code> with runtime detection</li><li>B) Separate <code>@sideband/transport-ws/browser</code> and <code>/node</code> imports</li></ul><p><strong>Chosen</strong>: A (single entry point)</p><p><strong>Rationale</strong>: Simpler for users. Bundlers tree-shake unused code anyway. The <code>platform</code> override enables testing browser code in Node. Conditional exports in package.json still provide optimal bundles.</p><h3 id="_2-websocket-subprotocol-enforcement-default" tabindex="-1">2. WebSocket subprotocol enforcement default <a class="header-anchor" href="#_2-websocket-subprotocol-enforcement-default" aria-label="Permalink to “2. WebSocket subprotocol enforcement default”">​</a></h3><p><strong>Options</strong>:</p><ul><li>A) Enforce by default (<code>requireSelection: true</code>)</li><li>B) Pass-through by default (<code>requireSelection: false</code>)</li></ul><p><strong>Chosen</strong>: B (pass-through by default)</p><p><strong>Rationale</strong>: Transport layer should be generic. WebSocket subprotocol enforcement is Sideband-specific policy that belongs in application configuration, not transport defaults. This keeps transport-ws usable for non-Sideband WebSocket connections without fighting defaults.</p><p>Sideband applications explicitly opt-in: <code>{ subprotocols: { offer: [&quot;sideband.v1&quot;], requireSelection: true } }</code>.</p><blockquote><p><strong>Note</strong>: WebSocket subprotocols (<code>Sec-WebSocket-Protocol</code>) are distinct from application protocols (SBP/SBRP). Transport handles WebSocket-level negotiation; application protocol negotiation happens at the SBP layer.</p></blockquote><h3 id="_3-auth-mode-in-browser" tabindex="-1">3. Auth mode in browser <a class="header-anchor" href="#_3-auth-mode-in-browser" aria-label="Permalink to “3. Auth mode in browser”">​</a></h3><p><strong>Options</strong>:</p><ul><li>A) Default to query (browsers can&#39;t set headers anyway)</li><li>B) Throw if mode not specified (force explicit choice)</li><li>C) Silently fall back to query</li></ul><p><strong>Chosen</strong>: B (throw if not specified)</p><p><strong>Rationale</strong>: Query params are visible in logs, URLs, and browser history. Developers must consciously accept this security tradeoff. Silent fallback (C) hides the problem. Default to insecure (A) is wrong.</p><h3 id="_4-send-buffer-overflow-behavior" tabindex="-1">4. Send buffer overflow behavior <a class="header-anchor" href="#_4-send-buffer-overflow-behavior" aria-label="Permalink to “4. Send buffer overflow behavior”">​</a></h3><p><strong>Options</strong>:</p><ul><li>A) Reject <code>send()</code> call with <code>buffer_overflow</code></li><li>B) Close connection</li><li>C) Block until buffer drains</li></ul><p><strong>Chosen</strong>: A (reject with <code>buffer_overflow</code>)</p><p><strong>Rationale</strong>: Rejection is explicit and recoverable. Connection close is surprising and unrecoverable. Blocking violates non-blocking <code>send()</code> semantics in ABI. Caller can check <code>pendingSendBytes</code> for proactive backpressure. Using dedicated <code>buffer_overflow</code> kind (vs <code>transport_failure</code>) enables distinct handling in retry logic.</p><h3 id="_5-inbound-buffer-overflow-behavior" tabindex="-1">5. Inbound buffer overflow behavior <a class="header-anchor" href="#_5-inbound-buffer-overflow-behavior" aria-label="Permalink to “5. Inbound buffer overflow behavior”">​</a></h3><p><strong>Options</strong>:</p><ul><li>A) Drop messages silently</li><li>B) Close connection with error</li><li>C) Apply backpressure to sender</li></ul><p><strong>Chosen</strong>: B (close connection)</p><p><strong>Rationale</strong>: Silent drops violate message delivery guarantees. WebSocket has no native backpressure mechanism for inbound data. Closing is the only safe option to prevent OOM.</p><p><strong>Normative rule</strong>: On inbound buffer overflow, implementations MUST close the connection with close code 1011 (&quot;Internal Error&quot;) and <code>TransportError(kind: &quot;buffer_overflow&quot;)</code>.</p><h3 id="_6-origin-validation-with-missing-origin-header" tabindex="-1">6. Origin validation with missing Origin header <a class="header-anchor" href="#_6-origin-validation-with-missing-origin-header" aria-label="Permalink to “6. Origin validation with missing Origin header”">​</a></h3><p><strong>Options</strong>:</p><ul><li>A) Reject connections without Origin</li><li>B) Allow connections without Origin</li></ul><p><strong>Chosen</strong>: B (allow)</p><p><strong>Rationale</strong>: Origin is browser-only. Non-browser clients (CLI tools, other servers) legitimately don&#39;t send it. Rejecting would break CLI-to-daemon and service-to-service use cases. Origin is for DNS rebinding protection, not authentication.</p><p><strong>Default policy</strong>:</p><ul><li>Localhost endpoints → <code>&quot;localhost&quot;</code> (allow only localhost origins)</li><li>Non-localhost endpoints → <code>&quot;any&quot;</code> (allow all origins)</li></ul><blockquote><p><strong>Warning</strong>: The <code>&quot;any&quot;</code> default is intentionally permissive for development. Production servers SHOULD configure <code>originPolicy</code> explicitly based on their security requirements.</p></blockquote><h3 id="_7-endpoint-normalization" tabindex="-1">7. Endpoint normalization <a class="header-anchor" href="#_7-endpoint-normalization" aria-label="Permalink to “7. Endpoint normalization”">​</a></h3><p><strong>Options</strong>:</p><ul><li>A) Full canonicalization (sort query params, normalize ports, trailing slashes)</li><li>B) Minimal validation (scheme check, strip hash only)</li></ul><p><strong>Chosen</strong>: B (minimal)</p><p><strong>Rationale</strong>: ABI says endpoint is opaque, for diagnostics only. Canonicalization creates false expectation that endpoints can be compared for equality. Different URLs should remain different endpoints.</p><h3 id="_8-server-websocket-subprotocol-selection" tabindex="-1">8. Server WebSocket subprotocol selection <a class="header-anchor" href="#_8-server-websocket-subprotocol-selection" aria-label="Permalink to “8. Server WebSocket subprotocol selection”">​</a></h3><p><strong>Options</strong>:</p><ul><li>A) Fixed list only (<code>offer: [&quot;sideband.v1&quot;]</code>), select first match</li><li>B) Callback for custom logic (<code>select: (offered) =&gt; ...</code>)</li><li>C) Both: list for common case, callback for advanced</li></ul><p><strong>Chosen</strong>: C (both)</p><p><strong>Rationale</strong>: Most servers just need a list. But version negotiation (&quot;prefer v2, fall back to v1&quot;) or custom logic (logging, metrics) needs a callback. Callback is proactive (called during handshake), not reactive (after selection).</p><h2 id="close-code-semantics" tabindex="-1">Close Code Semantics <a class="header-anchor" href="#close-code-semantics" aria-label="Permalink to “Close Code Semantics”">​</a></h2><p>Implementations MUST use these WebSocket close codes:</p><table tabindex="0"><thead><tr><th>Code</th><th>Condition</th><th>TransportErrorKind</th></tr></thead><tbody><tr><td>1000</td><td>Graceful close</td><td>(none)</td></tr><tr><td>1003</td><td>Text frame received</td><td><code>transport_failure</code></td></tr><tr><td>1009</td><td>Single message exceeds <code>maxMessageSize</code></td><td><code>message_too_large</code></td></tr><tr><td>1011</td><td>Inbound buffer overflow</td><td><code>buffer_overflow</code></td></tr></tbody></table><p><strong>Graceful close</strong>: Close code 1000 resolves the <code>closed</code> promise with <code>{ graceful: true }</code> and no <code>TransportError</code>. All other codes resolve with <code>{ graceful: false, error: TransportError(...) }</code>.</p><p><strong>1006 heuristic</strong>: Code 1006 (abnormal closure) provides no reason. Implementations MUST use traffic history to disambiguate:</p><ul><li>1006 + no bytes exchanged → <code>connection_refused</code> (connection failed before establishment)</li><li>1006 + bytes exchanged → <code>abnormal_close</code> (connection dropped mid-session)</li></ul><p>This heuristic requires internal traffic counters (<code>ioBytes: { sent, received }</code>). The counters need not be public API, but MUST be tracked for correct error classification.</p><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to “Non-goals”">​</a></h2><p>Explicitly out of scope for <code>@sideband/transport-ws</code>:</p><ul><li><strong>Reconnection / backoff</strong> → <code>@sideband/runtime</code> or <code>@sideband/peer</code></li><li><strong>Connection pooling</strong> → <code>@sideband/peer</code></li><li><strong>Protocol framing (SBP/SBRP)</strong> → <code>@sideband/protocol</code>, <code>@sideband/secure-relay</code></li><li><strong>Authentication verification</strong> → Relay server / <code>@sideband/runtime</code></li><li><strong>Message serialization</strong> → <code>@sideband/protocol</code></li><li><strong>Heartbeat policy</strong> → <code>@sideband/runtime</code></li></ul><p>Transport is minimal: it connects, sends bytes, receives bytes, and closes. Everything else belongs in higher layers.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>API is simple for common cases (<code>wsTransport()</code> + <code>wsEndpoint()</code>) while allowing advanced configuration</li><li>Security-sensitive choices (auth mode, origin validation) require explicit opt-in</li><li>Transport remains generic and reusable for non-Sideband WebSocket connections</li><li>Error handling is predictable: <code>buffer_overflow</code> is recoverable on send, fatal on receive</li><li>Close codes are deterministic and testable</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li>ADR-005: Transport ABI Package</li><li><code>docs/protocols/transport/websocket.md</code>: WebSocket-specific behavioral spec</li><li><code>docs/protocols/transport/errors.md</code>: Error taxonomy including <code>buffer_overflow</code></li><li><code>docs/protocols/transport/conformance.md</code>: Conformance test matrix</li></ul>',71)])])}const b=o(i,[["render",s]]);export{u as __pageData,b as default};
